	return (sizeof (uint32_t))*(max+1) + (sizeof(double))*3*(max+1) + (sizeof(double))*3*(max+1) + (sizeof(double))*3*(max+1) + (sizeof(double))*(max+1)+ sizeof(uint32_t);
